package com.dispatchpro.driver;
import android.app.*;
import android.content.Context;
import android.media.AudioManager;
import java.util.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33)
public class QaAudioNotificationsTest {
 Context c;NotificationManager manager;String ride=UUID.randomUUID().toString(),message=UUID.randomUUID().toString();
 @Before public void before(){c=RuntimeEnvironment.getApplication();manager=c.getSystemService(NotificationManager.class);manager.cancelAll();CommunicationNotifications.activate(c);c.getSharedPreferences("qa-audio",0).edit().clear().commit();CallAudioService.requested=false;c.getSystemService(AudioManager.class).setRingerMode(AudioManager.RINGER_MODE_NORMAL);manager.setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_ALL);Shadows.shadowOf((Application)c).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);}
 JSONObject data(boolean mine)throws Exception{return new JSONObject().put("chat",new JSONArray().put(new JSONObject().put("id",message).put("rideId",ride).put("mine",mine).put("text","QA only").put("senderName","مكتب QA"))).put("unread",new JSONObject().put(ride,2)).put("calls",new JSONArray());}
 @Test public void qaUsesDriverActivityAndNeverCustomerActivity(){assertTrue(CommunicationNotifications.driver(c));assertEquals(MainActivity.class,CommunicationNotifications.activity(c));}
 @Test public void applicationPreferencesMuteChatAndCallsWithoutChangingPhoneVolume(){CommunicationNotifications.configure(c);AudioManager audio=c.getSystemService(AudioManager.class);int before=audio.getStreamVolume(AudioManager.STREAM_NOTIFICATION);c.getSharedPreferences("driver-alerts",0).edit().putBoolean("sound",false).putBoolean("vibration",false).commit();for(String id:new String[]{CommunicationNotifications.CHAT,CommunicationNotifications.CALL}){NotificationChannel channel=manager.getNotificationChannel(CommunicationNotifications.preferenceChannel(c,id));assertNull(channel.getSound());assertFalse(channel.shouldVibrate());}assertEquals(before,audio.getStreamVolume(AudioManager.STREAM_NOTIFICATION));c.getSharedPreferences("driver-alerts",0).edit().putBoolean("enabled",false).commit();assertFalse(CommunicationNotifications.permitted(c));}
 @Test public void ownMessagesNeverNotify()throws Exception{CommunicationNotifications.sync(c,data(true),System.currentTimeMillis());assertEquals(0,manager.getActiveNotifications().length);}
 @Test public void reconnectNeverRealertsSameMessage()throws Exception{CommunicationNotifications.sync(c,data(false),System.currentTimeMillis());assertEquals(1,manager.getActiveNotifications().length);assertEquals(2,manager.getActiveNotifications()[0].getNotification().number);manager.cancelAll();CommunicationNotifications.sync(c,data(false),System.currentTimeMillis());assertEquals(0,manager.getActiveNotifications().length);}
 @Test public void visibleChatConsumesEventWithoutAlertingLater()throws Exception{c.getSharedPreferences("qa-audio",0).edit().putBoolean("foreground",true).putString("chat",ride).commit();CommunicationNotifications.sync(c,data(false),System.currentTimeMillis());assertEquals(0,manager.getActiveNotifications().length);c.getSharedPreferences("qa-audio",0).edit().putBoolean("foreground",false).commit();CommunicationNotifications.sync(c,data(false),System.currentTimeMillis());assertEquals(0,manager.getActiveNotifications().length);}
 @Test public void tripUpdatesUseQuietChannelAndRequestKeepsItsChannel(){DriverNotifications.show(c,"QA","QA","state",UUID.randomUUID().toString());Notification n=manager.getActiveNotifications()[0].getNotification();assertEquals("qa_driver_updates_silent_v1",n.getChannelId());assertNull(manager.getNotificationChannel(n.getChannelId()).getSound());manager.cancelAll();DriverNotifications.offer(c,ride,UUID.randomUUID().toString(),ride+":end",5000);assertEquals(DriverNotifications.channel(c),manager.getActiveNotifications()[0].getNotification().getChannelId());}
 @Test public void silentDndAndPreferencesSuppressShortTones(){assertTrue(QaSounds.enabled(c));c.getSystemService(AudioManager.class).setRingerMode(AudioManager.RINGER_MODE_SILENT);assertFalse(QaSounds.enabled(c));c.getSystemService(AudioManager.class).setRingerMode(AudioManager.RINGER_MODE_NORMAL);manager.setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_NONE);assertFalse(QaSounds.enabled(c));manager.setInterruptionFilter(NotificationManager.INTERRUPTION_FILTER_ALL);c.getSharedPreferences("driver-alerts",0).edit().putBoolean("sound",false).commit();assertFalse(QaSounds.enabled(c));}
 @Test public void acceptanceIsDurablyOnceAndCallsSuppressOtherTones(){String key=UUID.randomUUID().toString();QaSounds.play(c,"accepted",key);QaSounds.play(c,"accepted",key);assertEquals(Set.of("accepted:"+key),c.getSharedPreferences("qa-audio",0).getStringSet("seen",Set.of()));CallAudioService.requested=true;QaSounds.play(c,"accepted",UUID.randomUUID().toString());assertEquals(1,c.getSharedPreferences("qa-audio",0).getStringSet("seen",Set.of()).size());CallAudioService.requested=false;QaSounds.stop(c);}
 @Test public void offerRefreshNeverAlertsTwiceAndCanBeCancelled(){DriverNotifications.offer(c,ride,"",ride+":expiry",5000);assertEquals(1,manager.getActiveNotifications().length);DriverNotifications.close(c,"driver-offer-"+ride);DriverNotifications.offer(c,ride,"",ride+":expiry",5000);assertEquals(0,manager.getActiveNotifications().length);}
 @Test public void expiredOfferNotificationIsCancelledWithoutAnotherAlert(){DriverNotifications.offer(c,ride,"",ride+":expiry",1000);Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(2));assertEquals(0,manager.getActiveNotifications().length);}
 @Test public void incomingCallIsShownOnceAndTerminalStateCancelsItsRing()throws Exception{String id=UUID.randomUUID().toString();JSONObject call=new JSONObject().put("id",id).put("rideId",ride).put("peerName","QA office");CommunicationNotifications.showIncoming(c,call,40000);assertEquals(1,manager.getActiveNotifications().length);assertNotEquals(0,manager.getActiveNotifications()[0].getNotification().flags&Notification.FLAG_INSISTENT);manager.cancelAll();CommunicationNotifications.showIncoming(c,call,39000);assertEquals(0,manager.getActiveNotifications().length);CommunicationNotifications.finishCall(c,id,2);CommunicationNotifications.showIncoming(c,call,38000);assertEquals(0,manager.getActiveNotifications().length);}
}
